-- ---------------------------------------------------------------------------
-- Remise en conformite du referentiel OIC avec la source officielle UNESS
--
-- Source : livret.uness.fr/lisa/2026, table Cargo « Objectif_de_connaissance »,
-- lue le 18/09/2026 via l'API MediaWiki avec la session de la proprietaire.
--
-- Constat (comparaison ligne a ligne des 4872 objectifs officiels avec la
-- table oic_competences) :
--   identifiants presents .............. 4872 / 4872  (aucun manquant,
--                                        aucun en trop, aucun doublon)
--   rang correct ....................... 4872 / 4872
--   item parent correct ................ 4872 / 4872
--   INTITULE DIFFERENT ................. 2942 / 4872  (60 %)
--   RUBRIQUE DIFFERENTE ................ 4872 / 4872  (100 %)
--
-- Les intitules en base etaient tronques ou mutiles (« pratique medicale » au
-- lieu de « Connaitre la definition de la pratique medicale et connaitre la
-- signification de l'ethique »), et la rubrique avait ete attribuee par
-- position et non par contenu : « Genetique » revenait exactement 367 fois,
-- une fois par item, y compris sur l'item 1 (relation medecin-malade).
--
-- Cette migration remet les 4872 intitules, rubriques et ordres officiels.
-- Le squelette (identifiants, rangs, items parents) etait deja juste : il
-- n'est pas touche. Les colonnes description et url_source non plus.
--
-- Elle ne supprime AUCUNE ligne. Les 734 lignes IC-<n>-A/B semees par la
-- migration 20250706182945 restent en base ; le front ne les affiche plus
-- (predicat estCompetenceOICReelle, commit c6bb3634). Leur suppression
-- eventuelle est une decision separee.
-- ---------------------------------------------------------------------------

BEGIN;

-- Filet de securite : etat anterieur conserve, pour pouvoir revenir en arriere.
CREATE TABLE IF NOT EXISTS oic_competences_avant_uness_20260918 AS
  SELECT objectif_id, intitule, rubrique, ordre FROM public.oic_competences;

CREATE TEMP TABLE uness_officiel (
  objectif_id text PRIMARY KEY,
  intitule    text NOT NULL,
  rubrique    text,
  ordre       integer
) ON COMMIT DROP;


-- 1. Remise en conformite des 4872 objectifs.
UPDATE public.oic_competences c
   SET intitule   = u.intitule,
       rubrique   = u.rubrique,
       ordre      = COALESCE(u.ordre, c.ordre),
       updated_at = now()
  FROM uness_officiel u
 WHERE c.objectif_id = u.objectif_id
   AND (c.intitule IS DISTINCT FROM u.intitule
     OR c.rubrique IS DISTINCT FROM u.rubrique
     OR c.ordre    IS DISTINCT FROM COALESCE(u.ordre, c.ordre));

-- 2. Colonnes de remplissage : elles ne viennent pas d'UNESS, elles ont ete
--    fabriquees par generation automatique et repetent la meme phrase des
--    centaines de fois (« Acquisition des connaissances fondamentales en ... »).
--    Elles etaient affichees a l'etudiant comme si elles avaient un sens.
UPDATE public.oic_competences
   SET sommaire = NULL, mecanismes = NULL, indications = NULL,
       effets_indesirables = NULL, interactions = NULL,
       modalites_surveillance = NULL, causes_echec = NULL,
       contributeurs = NULL, titre_complet = NULL,
       updated_at = now()
 WHERE objectif_id ~ '^OIC-[0-9]{3}-[0-9]{2}-[AB]$';

-- 3. Controle : la migration echoue plutot que de laisser la base a moitie
--    corrigee.
DO $$
DECLARE n_faux integer;
BEGIN
  SELECT count(*) INTO n_faux
    FROM public.oic_competences c
    JOIN uness_officiel u USING (objectif_id)
   WHERE c.intitule IS DISTINCT FROM u.intitule
      OR c.rubrique IS DISTINCT FROM u.rubrique;
  IF n_faux <> 0 THEN
    RAISE EXCEPTION '% objectifs ne correspondent toujours pas a UNESS', n_faux;
  END IF;
END $$;

COMMIT;
